using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            var p = new Vector2(1100 / 1.25f, (822 + 55) / 1.25f);
            w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
            w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            double next = EditorApplication.timeSinceStartup + .5;
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                EditorApplication.update -= tick;
                var c = s.data.conclusions[0];
                string log = "Synthetic UI mouse/text enters claim, chooses insufficient, scrolls, consents and clicks save. API reads/asserts and loads only.\nfinalized=" + s.data.finalized + " choice=" + c.choice + " claim=" + c.claim + "\n";
                bool ok = s.data.finalized && c.choice == 0 && c.claim == "Chua du can cu ve thoi diem." && File.Exists(s.SavePath);
                for (int i = 0; i < 3; i++)
                    ok &= s.Load() && s.data.conclusions[0].claim == c.claim && s.data.conclusions[0].choice == 0;
                log += "three private reloads=" + ok;
                File.WriteAllText("Test/KetQua/investigation_r102/conclusion-ui-final.txt", log);
                ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/conclusion-ui-saved.png");
            };
            EditorApplication.update += tick;
            r.Log("UI save click sent; deferred assertions in conclusion-ui-final.txt");
        }
    }
}

